"""容器使用的无符号变长整数（LEB128）。

编码与 protobuf / 标准 LEB128 一致：每字节低 7 位携带数据，最高位为 1
表示后面还有字节。样本里 ``tag=300`` 写作 ``ac 02``，``tag=70000`` 写作
``f0 a2 04``，``length=256`` 写作 ``80 02``。

解码时区分两类错误：

* 数据在 varint 读完之前就结束了 —— ``truncated``；
* varint 本身非法（超过 :data:`MAX_BYTES` 字节 / 数值超过 64 位）——
  ``varint``。
"""

from __future__ import annotations

from .errors import WFormatError

__all__ = [
    "encode_uvarint",
    "decode_uvarint",
    "MAX_SHIFT",
    "MAX_VALUE",
    "MAX_BYTES",
]

#: 单个 uvarint 允许的最大位移。
MAX_SHIFT = 63

#: 单个 uvarint 能表示的最大数值（无符号 64 位）。
MAX_VALUE = (1 << (MAX_SHIFT + 1)) - 1

#: 单个 uvarint 允许的最大字节数。
MAX_BYTES = MAX_SHIFT // 7 + 1


def encode_uvarint(value):
    """把非负整数编码为 LEB128 字节串（最小编码，无冗余填充字节）。"""
    if isinstance(value, bool) or not isinstance(value, int):
        raise WFormatError("varint", "uvarint 只能编码整数，收到 %r" % (value,))
    if value < 0:
        raise WFormatError("varint", "uvarint 不能编码负数 %r" % (value,))
    if value > MAX_VALUE:
        raise WFormatError("varint", "uvarint 数值超出 64 位范围：%r" % (value,))
    out = bytearray()
    while True:
        group = value & 0x7F
        value >>= 7
        if value:
            out.append(group | 0x80)
        else:
            out.append(group)
            return bytes(out)


def decode_uvarint(buf, pos=0):
    """从 ``buf[pos:]`` 解出一个 uvarint，返回 ``(value, next_pos)``。"""
    return _decode_uvarint(buf, pos, len(buf))


def _decode_uvarint(buf, pos, end):
    """在 ``buf[pos:end]`` 范围内解出一个 uvarint。

    与 :func:`decode_uvarint` 相同，但把 ``end`` 当作可读区间的上界，
    这样调用方可以限制解析不要越过（例如）尾部校验和所在的区域。
    """
    if pos < 0:
        raise WFormatError("structure", "uvarint 偏移量非法：%r" % (pos,))
    if end > len(buf):
        end = len(buf)
    if pos >= end:
        raise WFormatError("truncated", "uvarint 数据不足")

    value = 0
    shift = 0
    index = pos
    while True:
        if index >= end:
            raise WFormatError("truncated", "uvarint 数据不完整")
        byte = buf[index]
        index += 1
        value |= (byte & 0x7F) << shift
        if not byte & 0x80:
            if value > MAX_VALUE:
                raise WFormatError("varint", "uvarint 数值超出 64 位范围")
            return value, index
        shift += 7
        if shift > MAX_SHIFT:
            raise WFormatError(
                "varint", "uvarint 超过 %d 字节上限" % (MAX_BYTES,)
            )

"""容器的流式读取入口。

:func:`iter_records` 是**惰性**的：它只用固定大小的 ``read(n)``（``n`` 为
正整数，见 :data:`CHUNK_SIZE`）向文件对象要数据，任意时刻内存里只保留一个
块级别的滑动缓冲区，因此可以处理远大于内存的容器。它从不调用无参
``read()`` / ``read(-1)`` / ``readlines()``。

取完最后一条记录之后仍会读尾部 4 字节并校验 CRC-32；校验和覆盖的是它之前
读到的全部字节（文件头 + 所有记录 + 对齐填充），所以校验和在流式读取过程
中是增量累加的。
"""

from __future__ import annotations

from .codec import align_pad
from .crc import CRC_SIZE, crc_update, unpack_crc
from .errors import WFormatError
from .header import HEADER_SIZE, parse_header
from .varint import MAX_SHIFT, MAX_VALUE

__all__ = ["CHUNK_SIZE", "iter_records", "read_all"]

#: 单次从底层文件对象请求的最大字节数。
CHUNK_SIZE = 4096


class _StreamReader(object):
    """带滑动缓冲区的顺序读取器，同时增量维护 CRC-32。"""

    def __init__(self, fileobj, chunk_size=CHUNK_SIZE):
        read = getattr(fileobj, "read", None)
        if not callable(read):
            raise WFormatError("structure", "需要带 read(n) 方法的文件对象")
        if not isinstance(chunk_size, int) or chunk_size <= 0:
            chunk_size = CHUNK_SIZE
        self._read = read
        self._chunk_size = chunk_size
        self._buf = bytearray()
        self._eof = False
        self._crc = 0
        self._offset = 0

    # -- 只读属性 -------------------------------------------------------
    @property
    def crc(self):
        """到目前为止（不含尾部校验和字段）所有已消费字节的 CRC-32。"""
        return self._crc & 0xFFFFFFFF

    @property
    def offset(self):
        """已消费的字节数。"""
        return self._offset

    @property
    def eof(self):
        return self._eof

    # -- 底层缓冲 -------------------------------------------------------
    def _refill(self, need):
        """尽量让缓冲区里至少有 ``need`` 字节，返回当前可用字节数。"""
        while not self._eof and len(self._buf) < need:
            chunk = self._read(self._chunk_size)
            if chunk is None:
                raise WFormatError("structure", "read(n) 返回了 None")
            if not isinstance(chunk, (bytes, bytearray, memoryview)):
                raise WFormatError(
                    "structure", "read(n) 必须返回字节，收到 %r" % (type(chunk).__name__,)
                )
            if len(chunk) == 0:
                self._eof = True
                break
            self._buf.extend(chunk)
        return len(self._buf)

    def _consume(self, count, digest=True):
        """取出并丢弃缓冲区前 ``count`` 字节，同时更新增量校验和。"""
        data = self._buf[:count]
        del self._buf[:count]
        self._offset += len(data)
        if digest:
            self._crc = crc_update(self._crc, data)
        return bytes(data)

    # -- 语义化读取 -----------------------------------------------------
    def read_exact(self, count, digest=True):
        """读取恰好 ``count`` 字节；不足则视为容器被截断。"""
        if count == 0:
            return b""
        if self._refill(count) < count:
            raise WFormatError("truncated", "容器数据提前结束")
        return self._consume(count, digest)

    def read_payload(self, count):
        """分块读取 ``count`` 字节的记录载荷。"""
        out = bytearray()
        while len(out) < count:
            want = min(count - len(out), self._chunk_size)
            have = self._refill(want)
            if have == 0:
                raise WFormatError("truncated", "记录载荷不完整")
            out.extend(self._consume(min(want, have)))
        return bytes(out)

    def read_uvarint(self):
        """从当前位置解出一个 uvarint。"""
        value = 0
        shift = 0
        index = 0
        while True:
            if index >= len(self._buf):
                if self._eof or self._refill(index + 1) <= index:
                    raise WFormatError("truncated", "uvarint 数据不完整")
            byte = self._buf[index]
            index += 1
            value |= (byte & 0x7F) << shift
            if not byte & 0x80:
                if value > MAX_VALUE:
                    raise WFormatError("varint", "uvarint 数值超出 64 位范围")
                self._consume(index)
                return value
            shift += 7
            if shift > MAX_SHIFT:
                raise WFormatError("varint", "uvarint 过长")

    def read_record(self):
        """读出一条记录，返回 ``(tag, payload)``；含对齐填充的消费。"""
        start = self._offset
        tag = self.read_uvarint()
        length = self.read_uvarint()
        payload = self.read_payload(length)
        pad = align_pad(self._offset - start)
        if pad:
            # 对齐填充同样计入校验和。
            self.read_exact(pad)
        return tag, payload

    def remaining(self, need):
        """在不消费数据的前提下，最多凑够 ``need`` 字节，返回可用字节数。"""
        return self._refill(need)

    def at_eof(self):
        """当前位置是否已经是文件末尾。"""
        if self._buf:
            return False
        return self._refill(1) == 0


def iter_records(fileobj):
    """惰性产出容器中的 ``(tag, payload)``。

    只使用固定大小的 ``read(n)``，不会把整个容器读进内存；取完最后一条记录
    后仍会校验尾部 CRC-32，失败抛 ``WFormatError(kind="checksum")``。
    """
    reader = _StreamReader(fileobj)
    header = reader.read_exact(HEADER_SIZE)
    _version, count = parse_header(header)

    for _ in range(count):
        # 记录区已经读完但 count 还没用完：结构自相矛盾。
        available = reader.remaining(CRC_SIZE + 1)
        if available <= CRC_SIZE:
            if available == CRC_SIZE:
                raise WFormatError("structure", "记录数与容器实际长度不符")
            raise WFormatError("truncated", "容器数据提前结束")
        tag, payload = reader.read_record()
        yield tag, payload

    stored = unpack_crc(reader.read_exact(CRC_SIZE, digest=False))
    if stored != reader.crc:
        raise WFormatError(
            "checksum",
            "尾部校验和不匹配：文件里是 %08x，实际算出 %08x" % (stored, reader.crc),
        )
    if not reader.at_eof():
        raise WFormatError("structure", "尾部校验和之后还有多余数据")


def read_all(fileobj):
    """把流式读取完整消费，返回 ``[(tag, payload), ...]``。"""
    return list(iter_records(fileobj))

